-- 📚 꼭집 주거 사전 — 든든전세 실사용면적 구간 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 🔵 2026-10-14 조건을 「주택면적 구분(실사용면적 기준)」 꼴로 좁힘 — 종전 「실사용면적」 낱말은 …20742(통합공공임대) 「실사용면적의 경미한 증감」 문장까지 세어 7이었다(든든전세는 6).
-- 확인 2026-10-14 · 실행 3.2초 · 결과(좁힌 조건으로 실행 — 실사용면적 6):
-- {"anns": 270, "by_std": {"SH 고유": 2, "공공임대(6·10·50년)": 17, "국민임대": 102, "매입임대": 77, "영구임대": 29, "전세임대": 4, "통합공공임대": 4, "행복주택": 29, "행복주택(신혼희망)": 6}, "실사용면적": 6, "실사용면적_ex": ["2015122300020873", "2015122300020843", "2015122300020835"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where true),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where true group by 1)q),'실사용면적',(select count(distinct announcement_id) from y where true and t~'주택\s*면적\s*구분\s*\(\s*실\s*사용\s*면적\s*기준\s*\)'),'실사용면적_ex',(select json_agg(i) from(select distinct announcement_id i from y where true and t~'주택\s*면적\s*구분\s*\(\s*실\s*사용\s*면적\s*기준\s*\)' order by 1 desc limit 3)q))j;
